  { id: 'a3', title: 'Startup Venture Certification', issuer: 'BeastBuck Ventures', level: 'Advanced', prereqs: 3 },
  { id: 'a4', title: 'AI Ethics & Governance', issuer: 'BeastBuck Research Lab', level: 'Intermediate', prereqs: 1 },
  { id: 'a5', title: 'Leadership Excellence Program', issuer: 'BeastBuck Academy', level: 'Expert', prereqs: 4 },
  { id: 'a6', title: 'Full-Stack Engineering', issuer: 'BeastBuck Academy', level: 'Advanced', prereqs: 3 },
