const MOCK_IN_PROGRESS = [
  { id: 'p1', title: 'Deep Learning Specialization', issuer: 'BeastBuck Academy', level: 'Expert', progress: 72, deadline: '2026-07-01' },
  { id: 'p2', title: 'Product Management Certification', issuer: 'BeastBuck Academy', level: 'Intermediate', progress: 45, deadline: '2026-08-15' },
  { id: 'p3', title: 'Systems Design Mastery', issuer: 'BeastBuck Academy', level: 'Master', progress: 18, deadline: '2026-09-30' },
];


function StatBar({ earnedCount, inProgressCount, availableCount }) {
  const stats = [
    { label: 'Total Earned', value: earnedCount, icon: Award, color: 'text-green-400' },
    { label: 'In Progress', value: inProgressCount, icon: Clock, color: 'text-orange-400' },
    { label: 'Available', value: availableCount, icon: Star, color: 'text-accent' },
    { label: 'Verification Rate', value: '100%', icon: Shield, color: 'text-purple-400' },
  ];

  return (
    <div className="mb-8 grid grid-cols-2 gap-4 md:grid-cols-4">
      {stats.map(s => (
        <div key={s.label} className="rounded-xl border border-border bg-white/[0.02] p-4">
          <div className="mb-2 flex items-center justify-between">
            <p className="text-xs font-bold uppercase tracking-widest text-text-muted">{s.label}</p>
            <s.icon className={`h-4 w-4 ${s.color}`} />
          </div>
          <p className="font-heading text-3xl font-black text-white">{s.value}</p>
        </div>
      ))}
    </div>
  );
}

function EarnedCard({ cert }) {
  return (
    <Card className="border-green-500/30 shadow-[0_0_20px_rgba(74,222,128,0.12)] transition-all hover:shadow-[0_0_30px_rgba(74,222,128,0.2)]">
      <CardContent className="p-5 pt-5">
        <div className="mb-3 flex items-start justify-between gap-2">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-green-500/15">
            <BadgeCheck className="h-5 w-5 text-green-400" />
          </div>
          <div className="flex items-center gap-2">
            <button className="rounded-lg p-1.5 text-text-muted hover:bg-white/5 hover:text-white transition-colors" title="Verify Certificate">
              <ExternalLink className="h-4 w-4" />
            </button>
            <button className="rounded-lg p-1.5 text-text-muted hover:bg-white/5 hover:text-white transition-colors" title="QR Code">
              <QrCode className="h-4 w-4" />
            </button>
          </div>
        </div>
        <h3 className="font-heading text-base font-bold text-white">{cert.title}</h3>
        <p className="mt-1 text-sm text-text-muted">{cert.issuer}</p>
        <div className="mt-4 flex items-center justify-between">
          <span className={`rounded-lg border px-2.5 py-1 text-[10px] font-bold uppercase tracking-widest ${LEVEL_STYLES[cert.level]}`}>
            {cert.level}
          </span>
          <span className="text-xs text-text-muted">{new Date(cert.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span>
        </div>
        {/* QR Code Placeholder */}
        <div className="mt-4 flex items-center justify-center rounded-lg border border-dashed border-green-500/20 bg-green-500/5 p-3">
          <div className="flex flex-col items-center gap-1.5">
            <QrCode className="h-8 w-8 text-green-400/50" />
