      <CardContent className="p-5 pt-5">
        <div className="mb-3 flex items-start justify-between gap-2">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent/10">
            <Award className="h-5 w-5 text-accent" />
          </div>
          <span className={`rounded-lg border px-2.5 py-1 text-[10px] font-bold uppercase tracking-widest ${LEVEL_STYLES[cert.level]}`}>
            {cert.level}
          </span>
        </div>
        <h3 className="font-heading text-base font-bold text-white">{cert.title}</h3>
        <p className="mt-1 text-sm text-text-muted">{cert.issuer}</p>
        <div className="mt-4 flex items-center justify-between">
          <span className="text-xs text-text-muted">{cert.prereqs} prerequisites</span>
          <Button size="sm" variant="secondary" className="text-xs">
            Start Path
