        </div>
        <h3 className="font-heading text-base font-bold text-white">{cert.title}</h3>
        <p className="mt-1 text-sm text-text-muted">{cert.issuer}</p>
        <div className="mt-4 space-y-2">
          <div className="flex items-center justify-between text-xs">
            <span className="text-text-muted">Progress</span>
            <span className="font-bold text-orange-400">{cert.progress}%</span>
          </div>
          <div className="h-2.5 w-full overflow-hidden rounded-full bg-white/10">
            <div
              className="h-full rounded-full bg-gradient-to-r from-orange-500 to-orange-400 transition-all"
              style={{ width: `${cert.progress}%` }}
            />
          </div>
          <p className="text-[11px] text-text-muted">
            Deadline: {new Date(cert.deadline).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

export default function AcademyCertifications() {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('earned');
  const [earnedCerts, setEarnedCerts] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    async function loadCerts() {
      if (user) {
        try {
          const certs = await CertificateService.getUserCertificates(user.uid);
          setEarnedCerts(certs || []);
        } catch (error) {
          console.error("Error loading certificates:", error);
        }
      }
      setIsLoading(false);
    }
    loadCerts();
  }, [user]);

  const tabs = [
    { key: 'earned', label: 'Earned', icon: CheckCircle2, count: earnedCerts.length },
    { key: 'available', label: 'Available', icon: Star, count: MOCK_AVAILABLE.length },
    { key: 'progress', label: 'In Progress', icon: Loader2, count: MOCK_IN_PROGRESS.length },
  ];

  return (
    <PageContainer>
      <PageHeader
        title="Certifications"
        description="Earn, track, and verify your professional certifications across all BeastBuck programs."
        action={
          <div className="flex h-12 w-12 items-center justify-center rounded-lg border border-accent/25 bg-accent/10 text-accent">
            <Award className="h-6 w-6" />
          </div>
        }
      />

      <StatBar earnedCount={earnedCerts.length} inProgressCount={MOCK_IN_PROGRESS.length} availableCount={MOCK_AVAILABLE.length} />

      {/* Tabs */}
      <div className="mb-8 flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
        {tabs.map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={cn(
              'flex shrink-0 items-center gap-2 rounded-xl px-5 py-3 text-sm font-bold transition-all',
              activeTab === tab.key
                ? 'bg-accent text-black shadow-[0_0_15px_rgba(0,240,255,0.3)]'
                : 'border border-border bg-surface/50 text-text-muted hover:text-white hover:border-white/20'
            )}
          >
            <tab.icon className={`h-4 w-4 ${activeTab === tab.key ? '' : tab.key === 'progress' ? '' : ''}`} />
            {tab.label}
            <span className={cn(
              'rounded-full px-2 py-0.5 text-xs font-bold',
              activeTab === tab.key ? 'bg-black/20 text-black' : 'bg-white/5 text-text-muted'
            )}>
              {tab.count}
            </span>
          </button>
        ))}
      </div>

      {/* Tab Content */}
      {isLoading ? (
        <div className="flex justify-center p-12"><Loader2 className="w-8 h-8 animate-spin text-accent" /></div>
      ) : (
        <>
          {activeTab === 'earned' && (
            <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
              {earnedCerts.length === 0 ? (
                <div className="col-span-full py-12 text-center text-text-muted border border-dashed border-border rounded-xl">
                  No certifications earned yet. Complete courses and paths to earn them.
                </div>
              ) : (
                earnedCerts.map(cert => (
                  <EarnedCard key={cert.id} cert={{
                    ...cert,
                    level: cert.metadata?.level || 'Foundation',
                    issuer: 'BeastBuck Academy',
                    date: cert.issuedAt?.toMillis() || 0
                  }} />
                ))
              )}
            </div>
          )}

          {activeTab === 'available' && (
            <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
              {MOCK_AVAILABLE.map(cert => (
                <AvailableCard key={cert.id} cert={cert} />
              ))}
            </div>
          )}

          {activeTab === 'progress' && (
            <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
              {MOCK_IN_PROGRESS.map(cert => (
                <InProgressCard key={cert.id} cert={cert} />
              ))}
            </div>
          )}
        </>
      )}
    </PageContainer>
  );
}

import { useEffect, useMemo, useState } from 'react';
import {
  Activity, BarChart3, TrendingUp, Users, FlaskConical, Package,
  RefreshCw, Zap } from 'lucide-react';
import { AdminService } from '../../services/firebase/admin';
import { AdminMetric, AdminPanel, LoadingRows } from './adminUtils';

// Simple bar chart renderer
function BarChart({ data, height = 80, color = 'rgba(0,240,255,0.7)', label }) {
  if (!data || data.length === 0) return <p className="text-sm text-text-muted">No data</p>;
  const max = Math.max(...data.map(d => d.value), 1);
  return (
    <div>
      {label && <p className="mb-2 text-xs font-bold uppercase tracking-widest text-text-muted">{label}</p>}
      <div className="flex items-end gap-1" style={{ height }}>
        {data.map((d, i) => (
          <div key={i} className="group relative flex-1 flex flex-col items-center justify-end">
            <div
              className="w-full rounded-t transition-all duration-500"
              style={{
                height: `${Math.max((d.value / max) * height, d.value > 0 ? 4 : 0)}px`,
                background: color,
                opacity: 0.7 + (i / data.length) * 0.3,
              }}
            />
            <div className="absolute -top-6 hidden rounded bg-black px-1.5 py-0.5 text-[10px] text-white group-hover:block">
              {d.value}
            </div>
          </div>
        ))}
      </div>
      <div className="mt-1 flex justify-between text-[10px] text-text-muted">
        {data.map((d, i) => (
          <span key={i} className="flex-1 truncate text-center">{d.label}</span>
        ))}
      </div>
    </div>
  );
}

function groupByMonth(items, dateField = 'createdAt') {
  const counts = {};
  const now = new Date();
  // last 6 months
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const key = `${d.toLocaleString('default', { month: 'short' })} ${d.getFullYear()}`;
    counts[key] = 0;
  }
  for (const item of items) {
    try {
      let d;
      const val = item[dateField];
      if (val && typeof val.toDate === 'function') d = val.toDate();
      else if (val) d = new Date(val);
      else continue;
      const key = `${d.toLocaleString('default', { month: 'short' })} ${d.getFullYear()}`;
      if (key in counts) counts[key]++;
    } catch {
      continue;
    }
  }
  return Object.entries(counts).map(([label, value]) => ({ label: label.split(' ')[0], value }));
}

function DonutProgress({ value, max, color, label }) {
  const pct = max > 0 ? Math.round((value / max) * 100) : 0;
  const r = 30;
  const circ = 2 * Math.PI * r;
  const dash = (pct / 100) * circ;

  return (
    <div className="flex flex-col items-center gap-1">
      <div className="relative">
        <svg width="80" height="80" viewBox="0 0 80 80">
          <circle cx="40" cy="40" r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="8" />
          <circle
            cx="40" cy="40" r={r}
            fill="none"
            stroke={color}
            strokeWidth="8"
            strokeDasharray={`${dash} ${circ - dash}`}
            strokeDashoffset={circ / 4}
            strokeLinecap="round"
          />
          <text x="40" y="44" textAnchor="middle" fontSize="14" fontWeight="bold" fill="white">{pct}%</text>
        </svg>
      </div>
      <p className="text-xs font-bold text-text-muted">{label}</p>
      <p className="text-sm font-black text-white">{value} / {max}</p>
    </div>
  );
}

export default function AdminAnalytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    try {
      setData(await AdminService.getAnalytics());
    } catch (err) {
      console.error('Admin analytics failed:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };
  useEffect(() => { load(); }, []);

  const metrics = useMemo(() => {
    if (!data) return [];
    const totalXP = data.members.reduce((sum, m) => sum + Number(m.xp || 0), 0);
    const activeMembers = data.members.filter(m => !m.suspended && !m.removed).length;
    return [
      { label: 'Total Members', value: data.members.length, icon: Users, color: 'accent' },
      { label: 'Active Members', value: activeMembers, icon: Users, color: 'success' },
      { label: 'Total Projects', value: data.projects.length, icon: TrendingUp, color: 'accent' },
      { label: 'Experiments', value: data.experiments.length, icon: FlaskConical, color: 'purple' },
      { label: 'Products', value: data.products.length, icon: Package, color: 'accent' },
      { label: 'Total XP Awarded', value: totalXP.toLocaleString(), icon: Zap, color: 'warning' },
      { label: 'XP Log Entries', value: data.xpLogs.length, icon: BarChart3, color: 'accent' },
      { label: 'Activity Logs', value: data.activity.length, icon: Activity, color: 'accent' },
    ];
  }, [data]);

  const memberGrowth = useMemo(() => data ? groupByMonth(data.members) : [], [data]);
  const projectGrowth = useMemo(() => data ? groupByMonth(data.projects) : [], [data]);
  const xpGrowth = useMemo(() => data ? groupByMonth(data.xpLogs) : [], [data]);
  const activityGrowth = useMemo(() => data ? groupByMonth(data.activity, 'timestamp') : [], [data]);

  // Role distribution
  const roleDistribution = useMemo(() => {
    if (!data) return [];
    const counts = {};
    for (const m of data.members) {
      const r = m.role || 'Unknown';
      counts[r] = (counts[r] || 0) + 1;
    }
    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [data]);

  // Top XP earners
  const topEarners = useMemo(() => {
    if (!data) return [];
    return [...data.members]
      .filter(m => m.xp > 0)
      .sort((a, b) => (b.xp || 0) - (a.xp || 0))
      .slice(0, 5);
  }, [data]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-heading text-lg font-bold text-white">Platform Analytics</h2>
          <p className="text-xs text-text-muted">Growth metrics, activity trends, and member stats</p>
        </div>
        <button
          onClick={() => load(true)}
          disabled={refreshing}
          className="flex items-center gap-2 rounded-xl border border-border bg-white/5 px-4 py-2 text-sm font-bold text-text-soft hover:text-white disabled:opacity-50"
        >
          <RefreshCw className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />
          Refresh
