              </div>

              <button
                disabled={!achievementTitle.trim()}
                onClick={() => run(
                  () => AdminService.grantAchievement(memberId, {
                    id: achievementTitle.toLowerCase().replace(/\s+/g, '-'),
                    title: achievementTitle,
                    rewardXP: 0,
                    grantedAt: new Date().toISOString(),
                  }, user.uid),
                  `Achievement "${achievementTitle}" granted.`,
                )}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-accent/20 to-accent-alt/20 border border-accent/20 py-2.5 text-sm font-bold text-accent transition-all hover:from-accent/30 disabled:opacity-50"
              >
                <Award className="h-4 w-4" /> Grant Achievement
              </button>
            </div>
          )}
        </AdminPanel>

        {/* Badges */}
        <AdminPanel title="Grant Badge" icon={BadgePlus}>
          {loading ? <LoadingRows count={3} /> : (
            <div className="space-y-4">
              <MemberPicker members={members} value={memberId} onChange={setMemberId} />

              <div>
                <label className="mb-1.5 block text-xs font-bold text-text-muted">Select Badge</label>
                <div className="grid grid-cols-2 gap-1.5 max-h-48 overflow-y-auto pr-1 custom-scrollbar">
                  {SPECIALIZATIONS.map(s => (
                    <button
                      key={s.id}
                      onClick={() => setBadge(s.id)}
                      className={`flex items-center gap-2 rounded-xl border px-2.5 py-2 text-left text-xs font-bold transition-all ${
                        badge === s.id
                          ? 'border-accent-alt/40 bg-accent-alt/10 text-accent-alt'
                          : 'border-border bg-white/5 text-text-muted hover:text-white'
                      }`}
                    >
                      <span className="text-base">{s.emoji || '🏷️'}</span>
                      <span className="truncate">{s.name}</span>
                    </button>
                  ))}
                </div>
              </div>

              <button
                disabled={!badge}
                onClick={() => run(
                  () => AdminService.assignSpecialization(memberId, badge, user.uid),
                  `Badge "${badge}" granted.`,
                )}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-accent-alt/20 to-accent/20 border border-accent-alt/20 py-2.5 text-sm font-bold text-accent-alt transition-all hover:from-accent-alt/30 disabled:opacity-50"
              >
                <BadgePlus className="h-4 w-4" /> Grant Badge
              </button>
            </div>
          )}
        </AdminPanel>
      </div>

      {/* XP Leaderboard Preview */}
      {!loading && members.length > 0 && (
        <AdminPanel title="XP Leaderboard Preview" icon={Trophy}>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5">
            {[...members]
              .sort((a, b) => (b.xp || 0) - (a.xp || 0))
              .slice(0, 10)
              .map((m, i) => (
                <div
                  key={m.id}
                  onClick={() => setMemberId(m.id)}
                  className={`flex cursor-pointer items-center gap-2.5 rounded-xl border p-3 transition-all hover:border-white/10 ${
                    m.id === memberId ? 'border-accent/40 bg-accent/5' : 'border-border bg-white/[0.02]'
                  }`}
                >
                  <span className={`shrink-0 font-heading text-sm font-black ${i < 3 ? 'text-status-warning' : 'text-text-muted'}`}>
                    #{i + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-bold text-white">{m.displayName || m.username}</p>
                    <p className="text-xs text-accent">{(m.xp || 0).toLocaleString()} XP</p>
                  </div>
                </div>
              ))}
          </div>
        </AdminPanel>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { FlaskConical, CheckCircle2, Star, AlertCircle } from 'lucide-react';
import { PageHeader, LoadingState } from '../../components/ui/UIElements';
import { SectionWrapper } from '../../components/layout/LayoutWrappers';
import { InnovationService } from '../../services/firebase/innovation';
import { useAuth } from '../auth/AuthContext';
import { formatDate } from '../../lib/dateUtils';

export default function AdminInnovation() {
  const { user } = useAuth();
  const [discoveries, setDiscoveries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('PENDING_REVIEW');
  const [actionLoading, setActionLoading] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const data = await InnovationService.getDiscoveries({ status: filter });
      setDiscoveries(data);
    } catch (err) {
      console.error('Failed to load discoveries:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, [filter]);

  const handleApprove = async (id) => {
    setActionLoading(id);
    try {
      await InnovationService.approveDiscovery(id, user.uid);
      await load();
    } catch (err) {
      console.error('Approve failed:', err);
    } finally {
      setActionLoading(null);
    }
  };

  const handleFeature = async (id) => {
    setActionLoading(id);
    try {
      await InnovationService.featureDiscovery(id, user.uid);
      await load();
    } catch (err) {
      console.error('Feature failed:', err);
    } finally {
      setActionLoading(null);
    }
  };

  return (
    <div className="space-y-8">
      <PageHeader
        title="Innovation Moderation"
        description="Review, approve, and feature member discoveries, research projects, and inventions."
        action={
          <div className="flex h-12 w-12 items-center justify-center rounded-lg border border-accent/25 bg-accent/10 text-accent">
            <FlaskConical className="h-6 w-6" />
          </div>
        }
      />

      {/* Filter Tabs */}
      <div className="flex flex-wrap gap-2">
        {['PENDING_REVIEW', 'APPROVED', 'FEATURED'].map(status => (
          <button
            key={status}
            onClick={() => setFilter(status)}
            className={`rounded-xl px-4 py-2 text-sm font-bold transition ${
              filter === status
                ? 'bg-accent text-black'
                : 'border border-border bg-surface/50 text-text-muted hover:text-white'
            }`}
          >
            {status.replace('_', ' ')}
          </button>
        ))}
      </div>

      <SectionWrapper>
        <h3 className="mb-6 font-heading text-xl font-bold text-white">Discoveries</h3>
        {loading ? (
          <LoadingState />
        ) : discoveries.length === 0 ? (
          <div className="py-12 text-center">
            <AlertCircle className="mx-auto mb-3 h-8 w-8 text-text-muted/50" />
            <p className="text-text-muted">No discoveries with status: {filter.replace('_', ' ')}</p>
          </div>
        ) : (
          <div className="space-y-4">
            {discoveries.map(d => (
              <div key={d.id} className="rounded-xl border border-border/50 bg-surface/30 p-5">
                <div className="flex items-start justify-between gap-4 mb-3">
                  <div>
                    <h4 className="font-bold text-white">{d.title}</h4>
                    <p className="text-sm text-text-muted mt-1">{d.description}</p>
                    <p className="mt-2 text-xs text-text-soft">{formatDate(d.timestamp)}</p>
                  </div>
                  <span className={`shrink-0 rounded-lg px-2.5 py-1 text-[10px] font-bold uppercase tracking-widest ${
                    d.status === 'FEATURED' ? 'bg-status-warning/10 text-status-warning' :
                    d.status === 'APPROVED' ? 'bg-status-success/10 text-status-success' :
                    'bg-white/5 text-text-muted'
                  }`}>{d.status.replace('_', ' ')}</span>
                </div>
                <div className="flex gap-2">
                  {d.status === 'PENDING_REVIEW' && (
                    <button
                      onClick={() => handleApprove(d.id)}
                      disabled={actionLoading === d.id}
                      className="flex items-center gap-1.5 rounded-lg bg-status-success/10 px-3 py-1.5 text-xs font-bold text-status-success transition hover:bg-status-success/20 disabled:opacity-50"
                    >
                      <CheckCircle2 className="h-3.5 w-3.5" />
                      {actionLoading === d.id ? 'Approving...' : 'Approve'}
                    </button>
                  )}
                  {d.status !== 'FEATURED' && (
                    <button
                      onClick={() => handleFeature(d.id)}
                      disabled={actionLoading === d.id}
                      className="flex items-center gap-1.5 rounded-lg bg-status-warning/10 px-3 py-1.5 text-xs font-bold text-status-warning transition hover:bg-status-warning/20 disabled:opacity-50"
                    >
                      <Star className="h-3.5 w-3.5" />
                      {actionLoading === d.id ? 'Featuring...' : 'Feature'}
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </SectionWrapper>
    </div>
  );
}

import { useEffect, useState, useMemo } from 'react';
import {
  UserMinus, UserPlus, Users, RefreshCw, ChevronDown, X } from 'lucide-react';
import { AdminService } from '../../services/firebase/admin';
import { OrganizationService } from '../../services/firebase/organization';
import { SPECIALIZATIONS } from '../../constants/specializations';
import { ROLES } from '../../constants/roles';
import { useAuth } from '../auth/AuthContext';
import {
  AdminPanel, AdminEmptyState, AdminActionButton, AdminToast, StatusBadge, LoadingRows } from './adminUtils';

const ROLE_OPTIONS = [
  { value: ROLES.MAIN_CEO, label: 'Main CEO' },
  { value: ROLES.CO_CEO, label: 'Co-CEO' },
  { value: ROLES.LEADER, label: 'Leader' },
  { value: ROLES.MEMBER, label: 'Member' },
  { value: ROLES.PENDING, label: 'Pending Member' },
];

const FILTER_OPTIONS = ['All', 'Active', 'Suspended', 'Removed', 'Pending'];

function getRoleVariant(role) {
  if (role === ROLES.MAIN_CEO || role === ROLES.CO_CEO) return 'accent';
  if (role === ROLES.LEADER) return 'purple';
  if (role === ROLES.MEMBER) return 'success';
  return 'warning';
}

export default function AdminMembers() {
  const { user } = useAuth();
  const [members, setMembers] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [labs, setLabs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [toast, setToast] = useState('');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('All');
  const [expandedId, setExpandedId] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const [nextMembers, organization] = await Promise.all([
        AdminService.getMembers(),
        OrganizationService.getOrganization(),
      ]);
      setMembers(nextMembers);
      setDepartments(organization.departments || []);
      setLabs(organization.labs || []);
    } catch (err) {
      console.error('Admin members failed:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const run = async (action, message) => {
    try {
      await action();
      setToast(message);
      await load();
    } catch (err) {
      setToast('Error: ' + err.message);
    }
  };

  const filtered = useMemo(() => {
    return members.filter(m => {
      const matchSearch = !search || [m.displayName, m.username, m.email]
        .join(' ').toLowerCase().includes(search.toLowerCase());
      const matchFilter =
        filter === 'All' ||
        (filter === 'Active' && !m.suspended && !m.removed && m.role !== ROLES.PENDING) ||
        (filter === 'Suspended' && m.suspended) ||
        (filter === 'Removed' && m.removed) ||
        (filter === 'Pending' && m.role === ROLES.PENDING);
      return matchSearch && matchFilter;
    });
  }, [members, search, filter]);

  return (
    <div className="space-y-6">
      <AdminPanel
        title="Member Management"
        icon={Users}
        action={
          <button
            onClick={load}
            disabled={loading}
            className="flex items-center gap-1.5 rounded-lg border border-border bg-white/5 px-3 py-1.5 text-xs font-bold text-text-soft hover:text-white transition-all"
          >
            <RefreshCw className={`h-3.5 w-3.5 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
        }
      >
        <AdminToast message={toast} onClear={() => setToast('')} />

        {/* Filters */}
        <div className="mb-4 flex flex-col gap-3 sm:flex-row">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-muted" />
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search members…"
              className="h-10 w-full rounded-xl border border-border bg-white/5 pl-9 pr-4 text-sm text-white placeholder:text-text-muted focus:border-accent/40 focus:outline-none"
            />
            {search && (
              <button onClick={() => setSearch('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-text-muted hover:text-white">
                <X className="h-4 w-4" />
              </button>
            )}
          </div>
          <div className="flex gap-1.5">
            {FILTER_OPTIONS.map(f => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`rounded-lg border px-3 py-1.5 text-xs font-bold transition-all ${
                  filter === f
                    ? 'border-accent/40 bg-accent/10 text-accent'
                    : 'border-border bg-white/5 text-text-muted hover:text-white'
                }`}
              >
                {f}
              </button>
            ))}
          </div>
        </div>

        {/* Count */}
        <p className="mb-3 text-xs text-text-muted">
          Showing <span className="font-bold text-white">{filtered.length}</span> of {members.length} members
        </p>

        {/* Member List */}
        {loading ? <LoadingRows count={6} /> : (
          <div className="space-y-2">
            {filtered.length === 0 ? (
              <AdminEmptyState icon={Users} title="No members found" message="Try adjusting your search or filter." />
            ) : filtered.map(member => (
              <div key={member.id} className="rounded-xl border border-border/60 bg-white/[0.02] transition-all hover:border-white/10 hover:bg-white/[0.04]">
                {/* Member Header Row */}
                <div
                  className="flex cursor-pointer items-center gap-3 p-3"
                  onClick={() => setExpandedId(expandedId === member.id ? null : member.id)}
                >
                  {/* Avatar */}
                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-accent/20 to-accent-alt/20 font-heading text-sm font-black text-white">
                    {(member.displayName || member.username || '?')[0].toUpperCase()}
                  </div>

                  {/* Info */}
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-bold text-white">{member.displayName || member.username}</span>
                      <StatusBadge variant={getRoleVariant(member.role)}>{member.role}</StatusBadge>
                      {member.suspended && <StatusBadge variant="danger">Suspended</StatusBadge>}
                      {member.removed && <StatusBadge variant="default">Removed</StatusBadge>}
                    </div>
                    <p className="mt-0.5 text-xs text-text-muted">@{member.username} · {member.xp || 0} XP · Lvl {member.level || 1}</p>
                  </div>

                  {/* Quick Actions */}
                  <div className="flex shrink-0 items-center gap-1.5">
                    <AdminActionButton
                      variant="success"
                      onClick={(e) => { e.stopPropagation(); run(() => AdminService.approveMember(member.id, user.uid), `${member.displayName || member.username} approved.`); }}
                      title="Approve"
                    >
                      <UserPlus className="h-3.5 w-3.5" />
                    </AdminActionButton>
                    <AdminActionButton
                      variant="danger"
                      onClick={(e) => { e.stopPropagation(); run(() => AdminService.suspendMember(member.id, user.uid), `${member.displayName || member.username} suspended.`); }}
                      title="Suspend"
                    >
                      <UserMinus className="h-3.5 w-3.5" />
                    </AdminActionButton>
                    <ChevronDown className={`h-4 w-4 text-text-muted transition-transform ${expandedId === member.id ? 'rotate-180' : ''}`} />
                  </div>
                </div>

                {/* Expanded Actions */}
                {expandedId === member.id && (
                  <div className="border-t border-border/60 p-3">
                    <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
                      {/* Role Promote */}
                      <div>
                        <label className="mb-1 block text-xs font-bold text-text-muted">Promote / Demote</label>
                        <select
                          value={member.role || 'Member'}
                          onChange={(e) => run(() => AdminService.promoteMember(member.id, e.target.value, user.uid), `Role changed to ${e.target.value}.`)}
                          className="h-9 w-full rounded-xl border border-border bg-white/5 px-3 text-xs text-white focus:border-accent/40 focus:outline-none"
                        >
                          {ROLE_OPTIONS.map(r => <option key={r.value} value={r.value}>{r.label}</option>)}
                        </select>
                      </div>

                      {/* Department */}
                      <div>
                        <label className="mb-1 block text-xs font-bold text-text-muted">Department</label>
                        <select
                          value={member.departmentId || ''}
                          onChange={(e) => run(() => AdminService.assignDepartment(member.id, e.target.value, user.uid), 'Department assigned.')}
                          className="h-9 w-full rounded-xl border border-border bg-white/5 px-3 text-xs text-white focus:border-accent/40 focus:outline-none"
                        >
                          <option value="">No Department</option>
                          {departments.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                        </select>
                      </div>

                      {/* Lab */}
                      <div>
                        <label className="mb-1 block text-xs font-bold text-text-muted">Lab</label>
                        <select
                          value={member.labId || ''}
                          onChange={(e) => run(() => AdminService.assignLab(member.id, e.target.value, user.uid), 'Lab assigned.')}
                          className="h-9 w-full rounded-xl border border-border bg-white/5 px-3 text-xs text-white focus:border-accent/40 focus:outline-none"
                        >
                          <option value="">No Lab</option>
                          {labs.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                        </select>
                      </div>

                      {/* Specialization */}
                      <div>
                        <label className="mb-1 block text-xs font-bold text-text-muted">Specialization</label>
                        <select
                          onChange={(e) => e.target.value && run(() => AdminService.assignSpecialization(member.id, e.target.value, user.uid), 'Specialization assigned.')}
                          className="h-9 w-full rounded-xl border border-border bg-white/5 px-3 text-xs text-white focus:border-accent/40 focus:outline-none"
                          defaultValue=""
                        >
                          <option value="">Add Specialization</option>
                          {SPECIALIZATIONS.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                      </div>
                    </div>

                    {/* Danger Actions */}
                    <div className="mt-3 flex flex-wrap gap-2 border-t border-border/40 pt-3">
                      <AdminActionButton variant="success" onClick={() => run(() => AdminService.approveMember(member.id, user.uid), 'Member approved.')}>
                        <UserPlus className="h-3.5 w-3.5" /> Approve
                      </AdminActionButton>
                      <AdminActionButton variant="warning" onClick={() => run(() => AdminService.suspendMember(member.id, user.uid), 'Member suspended.')}>
                        <UserMinus className="h-3.5 w-3.5" /> Suspend
                      </AdminActionButton>
                      <AdminActionButton
                        variant="danger"
                        onClick={() => {
                          if (window.confirm(`Remove ${member.displayName || member.username}? This action cannot be undone.`)) {
                            run(() => AdminService.removeMember(member.id, user.uid), 'Member removed.');
                          }
                        }}
                      >
                        <ShieldCheck className="h-3.5 w-3.5" /> Remove
                      </AdminActionButton>
                      {member.specializations?.length > 0 && (
                        <div className="flex flex-wrap gap-1.5">
                          {member.specializations.map(s => (
                            <StatusBadge key={s} variant="purple">{s}</StatusBadge>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </AdminPanel>
    </div>
  );
}

import { useEffect, useState } from 'react';
import {
  Lock, ShieldAlert, Save, RefreshCw, AlertTriangle,
  UserX, FileX, Settings, CheckCircle2, XCircle } from 'lucide-react';
import { AdminService } from '../../services/firebase/admin';
import { useAuth } from '../auth/AuthContext';
import { AdminPanel, AdminToast, StatusBadge } from './adminUtils';

const SECURITY_CONTROLS = [
  {
    field: 'maintenanceMode',
    title: 'Maintenance Mode',
    description: 'Signal that BeastBuck is temporarily under maintenance. Members will see a maintenance notice and cannot log in.',
    icon: Settings,
    impact: 'HIGH',
    color: 'warning',
    warningText: 'This will prevent ALL members from accessing the platform.',
  },
  {
    field: 'registrationLock',
    title: 'Registration Lock',
    description: 'Block all new direct sign-ups. Existing members are unaffected. New users cannot create accounts.',
    icon: UserX,
    impact: 'MEDIUM',
    color: 'accent',
    warningText: 'New users will be unable to register an account.',
  },
  {
    field: 'applicationLock',
    title: 'Application Lock',
    description: 'Pause the public membership application form. Pending applications are preserved but new submissions are blocked.',
    icon: FileX,
    impact: 'LOW',
    color: 'success',
    warningText: 'New membership applications will be paused.',
  },
];

const IMPACT_COLORS = {
  HIGH: 'danger',
  MEDIUM: 'warning',
  LOW: 'success',
};

function SecurityToggle({ control, value, onChange }) {
  const { field, title, description, icon: Icon, impact, color, warningText } = control;
  const isOn = Boolean(value);
  const impactVariant = IMPACT_COLORS[impact];

  const handleToggle = () => {
    if (!isOn) {
      if (!window.confirm(`Enable ${title}?\n\n${warningText}`)) return;
    }
    onChange(field, !isOn);
  };

  return (
    <div className={`rounded-xl border p-5 transition-all duration-300 ${
      isOn
        ? 'border-status-danger/30 bg-status-danger/5 shadow-[0_0_20px_rgba(255,42,42,0.05)]'
        : 'border-border bg-white/[0.02] hover:border-white/10'
    }`}>
      {/* Header */}
      <div className="mb-4 flex items-start justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className={`flex h-10 w-10 items-center justify-center rounded-xl ${
            isOn ? 'bg-status-danger/20 text-status-danger' : 'bg-white/5 text-text-muted'
          }`}>
            {isOn ? <Lock className="h-5 w-5" /> : <Icon className="h-5 w-5" />}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="font-bold text-white">{title}</h3>
              <StatusBadge variant={impactVariant}>{impact} IMPACT</StatusBadge>
            </div>
            <div className="mt-0.5 flex items-center gap-1.5">
              {isOn ? (
                <>
                  <span className="h-2 w-2 rounded-full bg-status-danger shadow-[0_0_6px_rgba(255,42,42,0.8)]" />
                  <span className="text-xs font-bold text-status-danger">ACTIVE</span>
                </>
              ) : (
                <>
                  <span className="h-2 w-2 rounded-full bg-text-muted" />
                  <span className="text-xs text-text-muted">Inactive</span>
                </>
              )}
            </div>
          </div>
        </div>

        {/* Big Toggle */}
        <button
          onClick={handleToggle}
          className={`relative h-7 w-13 shrink-0 rounded-full border transition-all duration-300 ${
            isOn
              ? 'border-status-danger bg-status-danger/20'
              : 'border-border bg-white/5'
          }`}
          style={{ width: '3.25rem' }}
        >
          <span
            className={`absolute top-0.5 h-6 w-6 rounded-full transition-all duration-300 ${
              isOn
                ? 'left-[calc(100%-1.75rem)] bg-status-danger shadow-[0_0_10px_rgba(255,42,42,0.6)]'
                : 'left-0.5 bg-white/30'
            }`}
          />
        </button>
      </div>

      <p className="text-sm leading-6 text-text-muted">{description}</p>

      {isOn && (
        <div className="mt-4 flex items-start gap-2 rounded-lg border border-status-danger/20 bg-status-danger/5 px-3 py-2">
          <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0 text-status-danger" />
          <p className="text-xs font-bold text-status-danger">{warningText}</p>
        </div>
      )}
    </div>
  );
}

export default function AdminSecurity() {
  const { user } = useAuth();
  const [config, setConfig] = useState({
    maintenanceMode: false,
    registrationLock: false,
    applicationLock: false,
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState('');
  const [hasChanges, setHasChanges] = useState(false);
  const [original, setOriginal] = useState(null);

  useEffect(() => {
    AdminService.getSecurityConfig()
      .then(c => {
        setConfig(c);
        setOriginal(c);
      })
      .catch(err => console.error('Security config failed:', err))
      .finally(() => setLoading(false));
  }, []);

  const handleChange = (field, value) => {
    setConfig(prev => {
      const next = { ...prev, [field]: value };
      setHasChanges(JSON.stringify(next) !== JSON.stringify(original));
      return next;
    });
  };

  const save = async () => {
    setSaving(true);
    try {
      await AdminService.updateSecurityConfig(config, user.uid);
      setOriginal(config);
      setHasChanges(false);
      setToast('Security settings saved successfully.');
    } catch (err) {
      setToast('Error: ' + err.message);
    } finally {
      setSaving(false);
    }
  };

  const reset = () => {
    setConfig(original);
    setHasChanges(false);
  };

  const activeCount = Object.values(config).filter(Boolean).length;

  return (
    <div className="space-y-6">
      <AdminToast message={toast} onClear={() => setToast('')} />

      {/* Status Banner */}
      {!loading && (
        <div className={`flex items-center justify-between rounded-xl border px-5 py-4 ${
          activeCount > 0
            ? 'border-status-danger/30 bg-status-danger/5'
            : 'border-status-success/30 bg-status-success/5'
        }`}>
          <div className="flex items-center gap-3">
            <div className={`flex h-10 w-10 items-center justify-center rounded-xl ${
              activeCount > 0 ? 'bg-status-danger/20 text-status-danger' : 'bg-status-success/20 text-status-success'
            }`}>
              {activeCount > 0 ? <XCircle className="h-5 w-5" /> : <CheckCircle2 className="h-5 w-5" />}
            </div>
            <div>
              <p className="font-bold text-white">
                {activeCount > 0 ? `${activeCount} Security Lock${activeCount > 1 ? 's' : ''} Active` : 'All Systems Normal'}
              </p>
              <p className="text-xs text-text-muted">
                {activeCount > 0 ? 'Platform is operating in restricted mode.' : 'No security restrictions are enabled.'}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {config.maintenanceMode && <StatusBadge variant="warning">Maintenance</StatusBadge>}
            {config.registrationLock && <StatusBadge variant="accent">Reg Locked</StatusBadge>}
            {config.applicationLock && <StatusBadge variant="default">App Locked</StatusBadge>}
          </div>
        </div>
      )}

      <AdminPanel title="Security Controls" icon={ShieldAlert}>
        {loading ? (
          <div className="space-y-4">
            {[1, 2, 3].map(i => <div key={i} className="h-32 animate-pulse rounded-xl bg-white/5" />)}
          </div>
        ) : (
          <div className="grid gap-4 md:grid-cols-3">
            {SECURITY_CONTROLS.map(control => (
              <SecurityToggle
                key={control.field}
                control={control}
                value={config[control.field]}
                onChange={handleChange}
              />
            ))}
          </div>
        )}

        {/* Save / Reset */}
        <div className="mt-6 flex items-center justify-between border-t border-border/60 pt-5">
          <div className="text-xs text-text-muted">
            {hasChanges ? (
              <span className="flex items-center gap-1.5 text-status-warning">
                <span className="h-1.5 w-1.5 rounded-full bg-status-warning" />
                Unsaved changes
              </span>
            ) : (
              <span className="flex items-center gap-1.5">
                <span className="h-1.5 w-1.5 rounded-full bg-status-success" />
                Settings saved
              </span>
            )}
          </div>
          <div className="flex gap-3">
            {hasChanges && (
              <button
                onClick={reset}
                className="rounded-xl border border-border bg-white/5 px-4 py-2 text-sm font-bold text-text-soft hover:text-white"
              >
                Reset
              </button>
            )}
            <button
              onClick={save}
              disabled={saving || !hasChanges}
              className="flex items-center gap-2 rounded-xl bg-gradient-to-r from-accent to-accent-alt px-6 py-2.5 text-sm font-bold text-background shadow-[0_0_20px_rgba(0,240,255,0.2)] transition-all hover:shadow-[0_0_30px_rgba(0,240,255,0.4)] disabled:opacity-50"
            >
              {saving ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
              {saving ? 'Saving…' : 'Save Settings'}
            </button>
          </div>
        </div>
      </AdminPanel>

      {/* Danger Zone */}
      <div className="rounded-xl border border-status-danger/20 bg-status-danger/5 p-5">
        <div className="mb-3 flex items-center gap-2">
          <AlertTriangle className="h-5 w-5 text-status-danger" />
          <h3 className="font-bold text-status-danger">Danger Zone</h3>
        </div>
        <p className="text-sm text-text-muted mb-4">
          These settings affect the entire platform and all members. Changes are logged in the audit trail.
          Always verify before enabling any restriction.
        </p>
        <div className="flex flex-wrap gap-2 text-xs text-text-muted">
          <span>✓ All changes are logged in Audit Trail</span>
          <span>·</span>
          <span>✓ Admin actor ID is recorded</span>
          <span>·</span>
          <span>✓ Timestamp preserved</span>
        </div>
      </div>
    </div>
  );
}

