import { useState, useEffect } from 'react';
import { WorkspaceService } from '../../services/firebase/workspace';
import { WhiteboardSyncService } from '../../services/realtime/whiteboardSync';
import { useAuth } from '../auth/AuthContext';
import Button from '../../components/ui/Button';
import { MousePointer2, Square, Circle, Type, Save, Trash2 } from 'lucide-react';

// Phase 1: Simple Canvas Board (Sticky Notes / Flow Diagramming)
export default function CanvasBoard({ workspaceId, boardId, type = 'whiteboard', onClose }) {
  const [elements, setElements] = useState([]);
  const [title, setTitle] = useState('Untitled Board');
  const [saving, setSaving] = useState(false);
  const [mode, setMode] = useState('select'); // select | rect | circle | text
  const [cursors, setCursors] = useState({});
  const { user } = useAuth();

  useEffect(() => {
    if(boardId !== 'new') {
       loadBoard();

       const unsubElements = WhiteboardSyncService.subscribeToElements(boardId, (serverElements) => {
          // Convert map to array for rendering
          setElements(Object.values(serverElements));
       });

       const unsubPresence = WhiteboardSyncService.subscribeToPresence(boardId, (presence) => {
          setCursors(presence);
       });

       const leaveWhiteboard = WhiteboardSyncService.joinWhiteboard(boardId, {
          uid: user.uid,
          name: user.displayName || user.email,
          color: '#' + Math.floor(Math.random()*16777215).toString(16) // Random cursor color
       });

       return () => {
          unsubElements();
          unsubPresence();
          leaveWhiteboard();
       };
    }
  }, [boardId, user]);

  const loadBoard = async () => {
     if(type === 'whiteboard') {
        const boards = await WorkspaceService.getWhiteboards(workspaceId);
        const b = boards.find(x => x.id === boardId);
        if(b) {
           setTitle(b.title || '');
           // Elements are now loaded via real-time listener above
        }
     } else {
        const maps = await WorkspaceService.getMindMaps(workspaceId);
        const m = maps.find(x => x.id === boardId);
        if(m) {
           setTitle(m.title || '');
           // Elements are now loaded via real-time listener above
        }
     }
  };

  const handleSave = async () => {
     setSaving(true);
     const data = { title };
     if(type === 'whiteboard') {
        // elements are synced in real-time, but we can save snapshots
        await WhiteboardSyncService.createSnapshot(boardId, elements, user.uid);
        await WorkspaceService.saveWhiteboard(boardId, workspaceId, data, false); // Just update title
     } else {
        await WhiteboardSyncService.createSnapshot(boardId, elements, user.uid);
        await WorkspaceService.saveMindMap(boardId, workspaceId, data, false);
     }
     setSaving(false);
  };

  const addElement = (shapeType) => {
     const newEl = {
        id: Date.now().toString(),
        type: shapeType,
        x: 100 + Math.random() * 50,
        y: 100 + Math.random() * 50,
        w: shapeType === 'text' ? 120 : 100,
        h: shapeType === 'text' ? 40 : 100,
        text: shapeType === 'text' ? 'New Text' : '',
        color: '#2b2b2b'
     };
     setMode('select');
     if (boardId !== 'new') {
        WhiteboardSyncService.addElement(boardId, newEl);
     } else {
        setElements([...elements, newEl]);
     }
  };

  const updateElement = (id, updates) => {
     if (boardId !== 'new') {
        WhiteboardSyncService.updateElement(boardId, id, updates);
     } else {
        setElements(elements.map(e => e.id === id ? { ...e, ...updates } : e));
     }
  };

  const deleteElement = (id) => {
     if (boardId !== 'new') {
        WhiteboardSyncService.removeElement(boardId, id);
     } else {
        setElements(elements.filter(e => e.id !== id));
     }
  };

  // Very basic dragging for Phase 1
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  const startDrag = (e, id, elX, elY) => {
     if(mode !== 'select') return;
     setDraggingId(id);
     setDragOffset({ x: e.clientX - elX, y: e.clientY - elY });
  };

  const onDrag = (e) => {
     if(draggingId) {
        updateElement(draggingId, {
           x: e.clientX - dragOffset.x,
           y: e.clientY - dragOffset.y
        });
     }

     if (boardId !== 'new' && user) {
        // We need to account for canvas bounds in a real implementation, using clientX/Y for simplicity here
        WhiteboardSyncService.updateCursor(boardId, user.uid, e.clientX, e.clientY);
     }
  };

  const stopDrag = () => {
     setDraggingId(null);
  };

  return (
    <div className="flex h-[80vh] flex-col rounded-xl border border-border bg-black/40 overflow-hidden relative">
      {/* Toolbar */}
      <div className="flex items-center justify-between border-b border-border bg-surface/80 px-4 py-2">
         <div className="flex items-center gap-4">
            <input type="text" value={title} onChange={e=>setTitle(e.target.value)} className="bg-transparent font-bold text-white outline-none w-48" placeholder="Board Title" />

            <div className="flex gap-1 bg-black/20 p-1 rounded-lg border border-border">
               <button onClick={()=>setMode('select')} className={`p-1.5 rounded ${mode==='select'?'bg-accent/20 text-accent':'text-text-muted hover:text-white'}`}><MousePointer2 className="h-4 w-4"/></button>
               <button onClick={()=>addElement('rect')} className={`p-1.5 rounded ${mode==='rect'?'bg-accent/20 text-accent':'text-text-muted hover:text-white'}`}><Square className="h-4 w-4"/></button>
               <button onClick={()=>addElement('circle')} className={`p-1.5 rounded ${mode==='circle'?'bg-accent/20 text-accent':'text-text-muted hover:text-white'}`}><Circle className="h-4 w-4"/></button>
               <button onClick={()=>addElement('text')} className={`p-1.5 rounded ${mode==='text'?'bg-accent/20 text-accent':'text-text-muted hover:text-white'}`}><Type className="h-4 w-4"/></button>
            </div>
         </div>

         <div className="flex gap-2">
            <Button variant="secondary" size="sm" onClick={onClose}>Close</Button>
            <Button size="sm" onClick={handleSave} disabled={saving}><Save className="mr-2 h-4 w-4"/> {saving ? 'Saving...' : 'Save'}</Button>
         </div>
      </div>

      {/* Canvas Area */}
      <div 
         className="flex-1 relative overflow-hidden bg-[url('/grid.svg')] bg-repeat opacity-90 cursor-crosshair"
         onMouseMove={onDrag}
         onMouseUp={stopDrag}
         onMouseLeave={stopDrag}
      >
         {elements.map(el => (
            <div 
               key={el.id}
               onMouseDown={(e) => startDrag(e, el.id, el.x, el.y)}
               className="absolute flex items-center justify-center border-2 border-transparent hover:border-accent/50 cursor-move group transition-colors"
               style={{
                  left: el.x,
                  top: el.y,
                  width: el.w,
                  height: el.h,
                  backgroundColor: el.type !== 'text' ? el.color : 'transparent',
                  borderRadius: el.type === 'circle' ? '50%' : '8px'
               }}
            >
               {el.type === 'text' || el.type === 'rect' || el.type === 'circle' ? (
                  <textarea 
                     value={el.text}
                     onChange={(e) => updateElement(el.id, { text: e.target.value })}
                     className="w-full h-full bg-transparent text-center text-white resize-none outline-none overflow-hidden placeholder-white/30"
                     placeholder={el.type === 'text' ? 'Type here...' : ''}
                  />
               ) : null}

               {/* Delete button (shows on hover) */}
               <button 
                  onClick={() => deleteElement(el.id)}
                  className="absolute -top-3 -right-3 hidden h-6 w-6 items-center justify-center rounded-full bg-status-danger text-white group-hover:flex"
               >
                  <Trash2 className="h-3 w-3" />
               </button>
            </div>
         ))}

         {/* Live Cursors */}
         {Object.entries(cursors).map(([uid, p]) => {
            if (uid === user?.uid || !p.cursor) return null;
            return (
               <div 
                 key={uid} 
                 className="absolute pointer-events-none z-50 flex items-center gap-1 transition-all duration-100 ease-linear"
                 style={{ left: p.cursor.x, top: p.cursor.y }}
               >
                  <MousePointer2 className="w-4 h-4" style={{ color: p.color || '#fff' }} fill={p.color || '#fff'} />
                  <span className="bg-black/80 text-white text-[10px] px-1.5 py-0.5 rounded whitespace-nowrap" style={{ backgroundColor: p.color || '#000' }}>
                     {p.name?.split(' ')[0]}
                  </span>
               </div>
            );
         })}
      </div>
      <div className="absolute bottom-4 left-4 right-4 text-center pointer-events-none">
         <p className="inline-block rounded-full bg-black/60 px-4 py-1 text-xs text-text-muted backdrop-blur">
            Phase 1 Canvas: Simple objects and dragging supported. More features coming soon.
         </p>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { WorkspaceService } from '../../services/firebase/workspace';
import Button from '../../components/ui/Button';
import { Card, CardHeader, CardTitle, CardContent } from '../../components/ui/Card';
import { Users, X, Shield, Activity, Trash2, ShieldAlert } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';

export default function CollaborationManager({ workspaceId, onClose }) {
  const { user } = useAuth();
  const [members, setMembers] = useState([]);
  const [activity, setActivity] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('members'); // members | activity

  useEffect(() => {
    loadData();
  }, [workspaceId]);

  const loadData = async () => {
    setLoading(true);
    const m = await WorkspaceService.getMembers(workspaceId);
    setMembers(m);

    if (activeTab === 'activity') {
      const a = await WorkspaceService.getActivity(workspaceId);
      setActivity(a);
    }
    setLoading(false);
  };

  const handleRemove = async (userId) => {
    if(!window.confirm("Are you sure you want to remove this member?")) return;
    await WorkspaceService.removeMember(workspaceId, userId);
    await WorkspaceService.logActivity(workspaceId, user.uid, `REMOVED_MEMBER_${userId}`);
    await loadData();
  };

  const handleTransfer = async (userId) => {
    if(!window.confirm("Transfer ownership? You will become an Editor.")) return;
    await WorkspaceService.addMember(workspaceId, userId, 'OWNER');
    await WorkspaceService.addMember(workspaceId, user.uid, 'EDITOR');
    await WorkspaceService.logActivity(workspaceId, user.uid, `TRANSFERRED_OWNERSHIP_TO_${userId}`);
    await loadData();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
      <Card className="w-full max-w-2xl bg-background border border-border shadow-2xl">
        <CardHeader className="border-b border-border bg-surface/50 p-4">
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2 text-lg">
              <Users className="h-5 w-5 text-accent" /> Manage Collaboration
            </CardTitle>
            <button onClick={onClose} className="text-text-muted hover:text-white transition"><X className="h-5 w-5" /></button>
          </div>
          <div className="mt-4 flex gap-4 text-sm font-bold">
             <button onClick={() => { setActiveTab('members'); loadData(); }} className={`${activeTab === 'members' ? 'text-accent border-b-2 border-accent' : 'text-text-muted'}`}>Members</button>
             <button onClick={() => { setActiveTab('activity'); loadData(); }} className={`${activeTab === 'activity' ? 'text-accent border-b-2 border-accent' : 'text-text-muted'}`}>Activity Log</button>
          </div>
        </CardHeader>
        <CardContent className="p-0 max-h-[60vh] overflow-y-auto">
          {loading ? (
             <div className="p-8 text-center text-text-muted">Loading...</div>
          ) : activeTab === 'members' ? (
            <div className="divide-y divide-border/50">
              {members.map(m => (
                <div key={m.userId} className="flex items-center justify-between p-4 hover:bg-white/[0.02]">
                  <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-accent/20 text-accent font-bold">
                       {m.userId.substring(0,2).toUpperCase()}
                    </div>
                    <div>
                      <p className="font-bold text-white">User {m.userId.substring(0,6)}</p>
                      <p className="text-xs text-text-muted">Joined {m.joinedAt?.toDate().toLocaleDateString()}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <span className="flex items-center gap-1 rounded-full bg-white/5 px-2.5 py-1 text-xs font-bold text-text-muted">
                      {m.role === 'OWNER' && <ShieldAlert className="h-3 w-3 text-status-warning" />}
                      {m.role === 'EDITOR' && <Shield className="h-3 w-3 text-accent" />}
                      {m.role}
                    </span>

                    {/* Simplified actions for phase 1 */}
                    {m.role !== 'OWNER' && (
                       <div className="flex gap-2">
                         <button onClick={() => handleTransfer(m.userId)} className="text-xs text-accent hover:underline">Transfer Ownership</button>
                         <button onClick={() => handleRemove(m.userId)} className="text-xs text-status-danger hover:underline"><Trash2 className="h-4 w-4"/></button>
                       </div>
                    )}
                  </div>
                </div>
              ))}

              <div className="p-4 bg-surface/30">
                 <h4 className="text-sm font-bold text-white mb-2">Invite Member</h4>
                 <div className="flex gap-2">
                    <input type="text" placeholder="User ID" className="flex-1 rounded border border-border bg-black/20 px-3 py-1.5 text-sm text-white" />
                    <select className="rounded border border-border bg-black/20 px-3 py-1.5 text-sm text-white">
                       <option>VIEWER</option>
                       <option>COMMENTER</option>
                       <option>EDITOR</option>
                    </select>
                    <Button size="sm">Invite</Button>
                 </div>
              </div>
            </div>
          ) : (
            <div className="divide-y divide-border/50 p-4">
               {activity.length === 0 ? (
                  <p className="text-center text-text-muted py-4">No activity yet.</p>
               ) : (
                  activity.map(a => (
                     <div key={a.id} className="py-2 flex items-start gap-3">
                        <Activity className="h-4 w-4 text-text-muted mt-0.5" />
                        <div>
                           <p className="text-sm text-white"><span className="text-accent">{a.userId.substring(0,6)}</span> {a.action.replace(/_/g, ' ').toLowerCase()}</p>
                           <p className="text-xs text-text-muted">{a.timestamp?.toDate().toLocaleString()}</p>
                        </div>
                     </div>
                  ))
               )}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import { useAuth } from '../auth/AuthContext';
import { WorkspaceService } from '../../services/firebase/workspace';
import { DocumentPresenceService } from '../../services/realtime/documentPresence';
import Button from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Save, ChevronLeft, History, Loader2, FileText, Sparkles, Lightbulb } from 'lucide-react';
import { AIContextPanel } from '../ai/AIContextPanel';

export default function DocumentEditor({ workspaceId, docId, onClose }) {
  const { user } = useAuth();
  const [title, setTitle] = useState('');
  const [visibility, setVisibility] = useState('WORKSPACE');
  const [loading, setLoading] = useState(docId !== 'new');
  const [saving, setSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState(null);
  const [activeEditors, setActiveEditors] = useState({});
  const [collaborationVersion, setCollaborationVersion] = useState(1);
  const [collaborationMode, setCollaborationMode] = useState('LIVE');

  // Create editor instance
  const editor = useEditor({
    extensions: [StarterKit],
    content: '',
    editorProps: {
      attributes: {
        class: 'prose prose-invert prose-sm sm:prose-base lg:prose-lg xl:prose-2xl m-5 focus:outline-none max-w-full',
      },
    },
    onUpdate: () => {
      debouncedSave();
    },
    onSelectionUpdate: ({ editor }) => {
       if (docId !== 'new' && user) {
           const { from } = editor.state.selection;
           DocumentPresenceService.updateCursor(docId, user.uid, { index: from });
       }
    }
  });

  // Debounced auto-save ref
  const saveTimeout = useRef(null);

  useEffect(() => {
    if (docId !== 'new') {
      loadDocument();

      const unsubscribePresence = DocumentPresenceService.subscribeToDocPresence(docId, (editors) => {
         setActiveEditors(editors);
      });

      const leavePresence = DocumentPresenceService.joinDocument(docId, {
         uid: user.uid,
         name: user.displayName || user.email,
         avatar: user.photoURL || ''
      });

      return () => {
         unsubscribePresence();
         leavePresence();
      };
    }
  }, [docId, user]);

  const loadDocument = async () => {
    setLoading(true);
    const doc = await WorkspaceService.getDocument(docId);
    if (doc) {
      setTitle(doc.title || '');
      setVisibility(doc.visibility || 'WORKSPACE');
      if (editor && !editor.isDestroyed) {
        editor.commands.setContent(doc.content || '');
      }
      setLastSaved(doc.lastEditedAt?.toDate());
      if (doc.collaborationVersion) setCollaborationVersion(doc.collaborationVersion);
      if (doc.collaborationMode) setCollaborationMode(doc.collaborationMode);
    }
    setLoading(false);
  };

  const handleManualSave = async () => {
    if (saveTimeout.current) clearTimeout(saveTimeout.current);
    await saveContent();
    // Also save a version history point
    if (docId !== 'new') {
      await WorkspaceService.saveDocumentVersion(docId, editor.getHTML(), user.uid);
    }
  };

  const saveContent = async () => {
    if (!editor) return;
    setSaving(true);
    const data = {
      title,
      visibility,
      content: editor.getHTML(),
      authorId: user.uid,
      lastEditor: user.uid,
      collaborationVersion: collaborationVersion + 1,
      collaborationMode,
    };

    // For 'new', we actually need to create it and then we can't easily swap the ID without a redirect.
    // In a real app we'd redirect to the actual URL `/workspace/:id/doc/:docId` upon first save.
    // Assuming docId is handled safely in WorkspaceDetail for now.

    if (docId !== 'new') {
      await WorkspaceService.saveDocument(docId, workspaceId, data, false, user.uid);
      setLastSaved(new Date());
    } else {
       // In complete implementation we generate ID and update parent state
       console.log('Would create new doc:', data);
    }

    setSaving(false);
  };

  const debouncedSave = () => {
    if (saveTimeout.current) clearTimeout(saveTimeout.current);
    setSaving(true);
    saveTimeout.current = setTimeout(() => {
      saveContent();
    }, 2000);
  };

  // Editor toolbar actions
  const toggleBold = () => editor?.chain().focus().toggleBold().run();
  const toggleItalic = () => editor?.chain().focus().toggleItalic().run();
  const toggleHeading = (level) => editor?.chain().focus().toggleHeading({ level }).run();
  const toggleBulletList = () => editor?.chain().focus().toggleBulletList().run();

  if (loading) {
     return <div className="flex h-64 items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-accent" /></div>;
  }

  return (
    <div className="flex h-screen flex-col bg-background">
      {/* Header */}
      <header className="flex items-center justify-between border-b border-border bg-surface/50 px-4 py-3">
        <div className="flex items-center gap-4">
          <button onClick={onClose} className="rounded-lg p-2 text-text-muted hover:bg-white/5 hover:text-white transition">
            <ChevronLeft className="h-5 w-5" />
          </button>
          <Input 
            value={title} 
            onChange={e => { setTitle(e.target.value); debouncedSave(); }} 
            placeholder="Untitled Document" 
            className="border-none bg-transparent text-lg font-bold outline-none ring-0 focus:ring-0 max-w-[300px]" 
          />
          <span className="text-xs text-text-muted">
            {saving ? 'Saving...' : lastSaved ? `Saved ${lastSaved.toLocaleTimeString()}` : 'Not saved'}
          </span>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex -space-x-2 mr-2">
            {Object.entries(activeEditors).map(([uid, editorProfile]) => (
                <div key={uid} className="w-6 h-6 rounded-full bg-accent/20 border border-surface flex items-center justify-center overflow-hidden" title={editorProfile.name}>
                   {editorProfile.avatar ? <img src={editorProfile.avatar} alt="Avatar" /> : <span className="text-[10px] text-accent font-bold">{editorProfile.name?.charAt(0)}</span>}
                </div>
            ))}
          </div>
          <select 
            value={visibility} 
            onChange={e => { setVisibility(e.target.value); debouncedSave(); }}
            className="rounded-lg border border-border bg-white/5 px-3 py-1.5 text-xs text-white outline-none"
          >
            <option value="PRIVATE">Private</option>
            <option value="WORKSPACE">Workspace</option>
            <option value="ORGANIZATION">Organization</option>
            <option value="PUBLIC">Public</option>
          </select>
          <Button variant="secondary" size="sm" onClick={handleManualSave}>
            <Save className="mr-2 h-4 w-4" /> Save v{collaborationVersion}
          </Button>
          <Button variant="ghost" size="sm">
            <History className="h-4 w-4" />
          </Button>
        </div>
      </header>

      {/* Editor & Sidebar */}
      <div className="flex flex-1 overflow-hidden">
        <div className="flex-1 overflow-y-auto">
          {/* Toolbar */}
          <div className="sticky top-0 z-10 flex gap-2 border-b border-border bg-surface/80 p-2 backdrop-blur-sm">
             <button onClick={() => toggleHeading(1)} className={`px-2 py-1 text-sm rounded ${editor?.isActive('heading', { level: 1 }) ? 'bg-accent/20 text-accent' : 'hover:bg-white/5'}`}>H1</button>
             <button onClick={() => toggleHeading(2)} className={`px-2 py-1 text-sm rounded ${editor?.isActive('heading', { level: 2 }) ? 'bg-accent/20 text-accent' : 'hover:bg-white/5'}`}>H2</button>
             <div className="w-px bg-border/50 mx-1"></div>
             <button onClick={toggleBold} className={`px-2 py-1 text-sm rounded font-bold ${editor?.isActive('bold') ? 'bg-accent/20 text-accent' : 'hover:bg-white/5'}`}>B</button>
             <button onClick={toggleItalic} className={`px-2 py-1 text-sm rounded italic ${editor?.isActive('italic') ? 'bg-accent/20 text-accent' : 'hover:bg-white/5'}`}>I</button>
             <div className="w-px bg-border/50 mx-1"></div>
             <button onClick={toggleBulletList} className={`px-2 py-1 text-sm rounded ${editor?.isActive('bulletList') ? 'bg-accent/20 text-accent' : 'hover:bg-white/5'}`}>List</button>
          </div>

          <div className="p-8 pb-32">
             <EditorContent editor={editor} />
          </div>
        </div>

        {/* AI Sidebar */}
        <div className="w-80 border-l border-border bg-surface/30 flex flex-col p-4">
           <h3 className="font-bold text-sm text-text-muted uppercase tracking-widest mb-4">Document AI</h3>
           <AIContextPanel 
              actions={[
                 { label: 'Summarize Document', prompt: 'Please summarize this document in 3 bullet points.', icon: FileText },
                 { label: 'Improve Writing', prompt: 'Review this document and suggest improvements for clarity and tone.', icon: Sparkles },
                 { label: 'Generate Ideas', prompt: 'Based on this document, brainstorm 5 follow-up ideas or next steps.', icon: Lightbulb }
              ]}
           />
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { WorkspaceService } from '../../services/firebase/workspace';
import { useAuth } from '../auth/AuthContext';
import Button from '../../components/ui/Button';
import { Plus, Search, Pin, Trash2, Loader2, X } from 'lucide-react';
import { formatDistanceToNow } from '../../lib/dateUtils';

export default function NotesManager({ workspaceId }) {
  const { user } = useAuth();
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // Note editor modal state
  const [isEditing, setIsEditing] = useState(false);
  const [currentNote, setCurrentNote] = useState({ id: 'new', title: '', content: '', tags: '', isPinned: false, color: 'bg-surface' });
  const [saving, setSaving] = useState(false);

  const colors = [
     'bg-surface', 
     'bg-accent/10 border-accent/30', 
     'bg-status-success/10 border-status-success/30', 
     'bg-status-warning/10 border-status-warning/30', 
     'bg-status-danger/10 border-status-danger/30'
  ];

  useEffect(() => {
    loadNotes();
  }, [workspaceId]);

  const loadNotes = async () => {
    setLoading(true);
    const fetched = await WorkspaceService.getNotes(workspaceId);
    setNotes(fetched);
    setLoading(false);
  };

  const handleSave = async () => {
    setSaving(true);
    const data = {
       title: currentNote.title,
       content: currentNote.content,
       tags: currentNote.tags ? currentNote.tags.split(',').map(t=>t.trim()) : [],
       isPinned: currentNote.isPinned,
       color: currentNote.color,
       authorId: user.uid
    };

    await WorkspaceService.saveNote(currentNote.id, workspaceId, data, currentNote.id === 'new', user.uid);
    setSaving(false);
    setIsEditing(false);
    loadNotes();
  };

  const handleDelete = async (id) => {
    if(confirm('Delete this note?')) {
       await WorkspaceService.deleteNote(id, workspaceId);
       loadNotes();
    }
  };

  const togglePin = async (note) => {
    await WorkspaceService.saveNote(note.id, workspaceId, { isPinned: !note.isPinned }, false, user.uid);
    loadNotes();
  };

  const openEditor = (note = { id: 'new', title: '', content: '', tags: '', isPinned: false, color: 'bg-surface' }) => {
    setCurrentNote({
       ...note,
       tags: Array.isArray(note.tags) ? note.tags.join(', ') : ''
    });
    setIsEditing(true);
  };

  const filtered = notes.filter(n => 
     (n.title?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      n.content?.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const pinned = filtered.filter(n => n.isPinned);
  const unpinned = filtered.filter(n => !n.isPinned);

  if (loading) {
     return <div className="py-12 flex justify-center"><Loader2 className="w-8 h-8 animate-spin text-accent"/></div>;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-start sm:items-center">
         <div className="relative w-full max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-text-muted" />
            <input 
               type="text"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
               placeholder="Search notes..."
               className="w-full h-10 bg-white/5 border border-border rounded-xl pl-9 pr-4 text-sm text-white focus:ring-2 focus:ring-accent outline-none"
            />
         </div>
         <Button onClick={() => openEditor()}><Plus className="w-4 h-4 mr-2" /> New Note</Button>
      </div>

      {notes.length === 0 ? (
         <div className="text-center py-16 border border-dashed border-border rounded-xl">
            <h3 className="text-lg font-bold text-white mb-2">No notes yet</h3>
            <p className="text-text-muted text-sm mb-4">Capture ideas, meeting notes, and quick thoughts.</p>
            <Button variant="secondary" onClick={() => openEditor()}>Create Note</Button>
         </div>
      ) : (
         <div className="space-y-8">
            {pinned.length > 0 && (
               <div className="space-y-3">
                  <h4 className="text-xs font-bold text-text-muted uppercase tracking-widest flex items-center gap-2"><Pin className="w-3 h-3"/> Pinned Notes</h4>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                     {pinned.map(note => <NoteCard key={note.id} note={note} onEdit={()=>openEditor(note)} onDelete={()=>handleDelete(note.id)} onPin={()=>togglePin(note)} />)}
                  </div>
               </div>
            )}

            {unpinned.length > 0 && (
               <div className="space-y-3">
                  {pinned.length > 0 && <h4 className="text-xs font-bold text-text-muted uppercase tracking-widest">Other Notes</h4>}
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                     {unpinned.map(note => <NoteCard key={note.id} note={note} onEdit={()=>openEditor(note)} onDelete={()=>handleDelete(note.id)} onPin={()=>togglePin(note)} />)}
                  </div>
               </div>
            )}
         </div>
      )}

      {/* Editor Modal */}
      {isEditing && (
         <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="bg-surface border border-border rounded-2xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-center p-4 border-b border-border">
                  <input 
                     value={currentNote.title} 
                     onChange={e=>setCurrentNote({...currentNote, title: e.target.value})} 
                     placeholder="Note Title" 
                     className="bg-transparent text-lg font-bold text-white outline-none placeholder:text-text-muted/50 flex-1"
                  />
                  <div className="flex gap-2">
                     <button onClick={()=>setCurrentNote({...currentNote, isPinned: !currentNote.isPinned})} className={`p-2 rounded-lg ${currentNote.isPinned ? 'bg-accent/20 text-accent' : 'hover:bg-white/5 text-text-muted'}`}>
                        <Pin className="w-4 h-4" />
                     </button>
                     <button onClick={()=>setIsEditing(false)} className="p-2 rounded-lg hover:bg-white/5 text-text-muted"><X className="w-4 h-4"/></button>
                  </div>
               </div>
               <div className="p-4 flex-1 overflow-y-auto">
                  <textarea 
                     value={currentNote.content}
                     onChange={e=>setCurrentNote({...currentNote, content: e.target.value})}
                     placeholder="Write your note here..."
                     className="w-full h-full min-h-[300px] bg-transparent text-sm text-text-soft outline-none resize-none placeholder:text-text-muted/50"
                  />
               </div>
               <div className="p-4 border-t border-border flex flex-wrap gap-4 items-center justify-between bg-black/20 rounded-b-2xl">
                  <div className="flex items-center gap-2">
                     {colors.map(c => (
                        <button 
                           key={c} 
                           onClick={()=>setCurrentNote({...currentNote, color: c})}
                           className={`w-6 h-6 rounded-full border-2 ${currentNote.color === c ? 'border-white' : 'border-transparent'} ${c.split(' ')[0]}`}
                        />
                     ))}
                  </div>
                  <input 
                     type="text" 
                     value={currentNote.tags} 
                     onChange={e=>setCurrentNote({...currentNote, tags: e.target.value})} 
                     placeholder="Tags (comma separated)" 
                     className="bg-white/5 border border-border rounded-lg px-3 py-1.5 text-xs text-white outline-none focus:border-accent w-48"
                  />
                  <div className="flex gap-2">
                     <Button variant="secondary" onClick={()=>setIsEditing(false)}>Cancel</Button>
                     <Button onClick={handleSave} disabled={saving}>{saving ? 'Saving...' : 'Save Note'}</Button>
                  </div>
               </div>
            </div>
         </div>
      )}
    </div>
  );
}

function NoteCard({ note, onEdit, onDelete, onPin }) {
   return (
      <div className={`relative group rounded-xl border p-4 flex flex-col h-48 transition-all hover:scale-[1.02] cursor-pointer ${note.color || 'bg-surface border-border'}`} onClick={onEdit}>
         <div className="flex justify-between items-start mb-2">
            <h3 className="font-bold text-white text-sm line-clamp-1">{note.title || 'Untitled Note'}</h3>
            <button onClick={(e)=>{e.stopPropagation(); onPin();}} className={`p-1 rounded opacity-0 group-hover:opacity-100 transition ${note.isPinned ? 'text-accent opacity-100' : 'text-text-muted hover:text-white'}`}>
               <Pin className="w-3 h-3" />
            </button>
         </div>
         <p className="text-xs text-text-soft line-clamp-4 flex-1 whitespace-pre-wrap">{note.content}</p>
         <div className="mt-4 flex items-center justify-between">
            <p className="text-[10px] text-text-muted uppercase tracking-widest">{note.updatedAt ? formatDistanceToNow(note.updatedAt.toDate()) : 'Just now'}</p>
            <div className="flex gap-1">
               <button onClick={(e)=>{e.stopPropagation(); onDelete();}} className="p-1.5 rounded-lg text-text-muted hover:bg-status-danger/20 hover:text-status-danger opacity-0 group-hover:opacity-100 transition">
                  <Trash2 className="w-3 h-3" />
               </button>
            </div>
         </div>
      </div>
   );
}

import { useState, useEffect } from 'react';
import { WorkspaceService } from '../../services/firebase/workspace';
import Button from '../../components/ui/Button';
import { PlusCircle, Edit3 } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';

export default function ResearchNotebookEditor({ workspaceId, notebookId, onClose }) {
  const { user } = useAuth();
  const [notebook, setNotebook] = useState(null);
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);

  // New entry state
  const [showNew, setShowNew] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newContent, setNewContent] = useState('');
  const [newType, setNewType] = useState('OBSERVATION');

  useEffect(() => {
    loadData();
  }, [notebookId]);

  const loadData = async () => {
    setLoading(true);
    // Ideally fetch notebook metadata too if needed
    const e = await WorkspaceService.getNotebookEntries(notebookId);
    setEntries(e);
    setLoading(false);
  };

  const handleSaveEntry = async () => {
    if(!newTitle.trim() || !newContent.trim()) return;

    // Fake ID for Phase 1 (in real app, docRef.id is generated)
    const entryId = `entry_${Date.now()}`;

    await WorkspaceService.saveNotebookEntry(notebookId, entryId, {
       title: newTitle,
       content: newContent,
       type: newType,
       authorId: user.uid
    }, true);

    setNewTitle('');
    setNewContent('');
    setShowNew(false);
    await loadData();
  };

  if (loading) return <div className="p-12 text-center text-text-muted">Loading notebook...</div>;

  const typeColors = {
     OBSERVATION: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
     HYPOTHESIS: 'bg-purple-500/20 text-purple-400 border-purple-500/30',
     EXPERIMENT: 'bg-orange-500/20 text-orange-400 border-orange-500/30',
     RESULT: 'bg-green-500/20 text-green-400 border-green-500/30',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
         <h2 className="text-xl font-bold text-white">Research Log</h2>
         <Button onClick={() => setShowNew(true)}><PlusCircle className="mr-2 h-4 w-4"/> Add Entry</Button>
      </div>

      {showNew && (
         <div className="rounded-xl border border-accent/40 bg-accent/5 p-4 space-y-4">
            <h3 className="font-bold text-white">New Entry</h3>
            <div className="flex gap-4">
               <select value={newType} onChange={e=>setNewType(e.target.value)} className="w-40 rounded border border-border bg-black/20 p-2 text-sm text-white">
                  <option value="OBSERVATION">Observation</option>
                  <option value="HYPOTHESIS">Hypothesis</option>
                  <option value="EXPERIMENT">Experiment</option>
                  <option value="RESULT">Result</option>
               </select>
               <input type="text" value={newTitle} onChange={e=>setNewTitle(e.target.value)} placeholder="Entry Title" className="flex-1 rounded border border-border bg-black/20 p-2 text-sm text-white" />
            </div>
            <textarea value={newContent} onChange={e=>setNewContent(e.target.value)} placeholder="Details..." rows={4} className="w-full rounded border border-border bg-black/20 p-2 text-sm text-white" />
            <div className="flex justify-end gap-2">
               <Button variant="ghost" onClick={() => setShowNew(false)}>Cancel</Button>
               <Button onClick={handleSaveEntry}>Save Entry</Button>
            </div>
         </div>
      )}

      <div className="space-y-4 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-border before:to-transparent">
         {entries.map((entry, i) => (
            <div key={entry.id} className="relative flex items-center justify-between md:justify-normal md:odd:flex-row-reverse group is-active">
               <div className="flex items-center justify-center w-10 h-10 rounded-full border-4 border-background bg-surface/80 text-text-muted group-[.is-active]:text-accent group-[.is-active]:border-accent/30 shrink-0 md:order-1 md:group-odd:-translate-x-1/2 md:group-even:translate-x-1/2 shadow">
                  <Edit3 className="h-4 w-4" />
               </div>
               <div className="w-[calc(100%-4rem)] md:w-[calc(50%-2.5rem)] p-4 rounded-xl border border-border bg-white/[0.02] hover:bg-white/[0.04] transition">
                  <div className="flex items-center justify-between mb-2">
                     <span className={`px-2 py-0.5 text-[10px] font-bold rounded-full border uppercase tracking-widest ${typeColors[entry.type] || typeColors.OBSERVATION}`}>
                        {entry.type}
                     </span>
                     <time className="text-xs text-text-muted">{entry.timestamp?.toDate().toLocaleDateString()}</time>
                  </div>
                  <h4 className="font-bold text-white mb-2">{entry.title}</h4>
                  <p className="text-sm text-text-soft whitespace-pre-wrap">{entry.content}</p>
               </div>
            </div>
         ))}
         {entries.length === 0 && !showNew && (
            <p className="text-center text-text-muted italic py-8">No research entries yet. Start logging observations!</p>
         )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { WorkspaceService } from '../../services/firebase/workspace';
import { PageContainer, SectionWrapper } from '../../components/layout/LayoutWrappers';
import { PageHeader } from '../../components/ui/UIElements';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import { FolderKanban, PlusCircle, LayoutDashboard, Loader2 } from 'lucide-react';
import { Input } from '../../components/ui/Input';

export default function WorkspaceDashboard() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [workspaces, setWorkspaces] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isCreating, setIsCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const [newDesc, setNewDesc] = useState('');

  useEffect(() => {
    if (user) loadWorkspaces();
  }, [user]);

  const loadWorkspaces = async () => {
    setLoading(true);
    const w = await WorkspaceService.getUserWorkspaces(user.uid);
    setWorkspaces(w);
    setLoading(false);
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    if (!newName.trim()) return;
    setIsCreating(true);
    const id = await WorkspaceService.createWorkspace({
      name: newName,
      description: newDesc,
      ownerId: user.uid,
      type: 'PERSONAL'
    });
    setNewName('');
    setNewDesc('');
    setIsCreating(false);
    navigate(`/workspace/${id}`);
  };

  if (loading) {
    return (
      <PageContainer>
        <div className="flex h-64 items-center justify-center">
          <Loader2 className="h-8 w-8 animate-spin text-accent" />
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      <PageHeader
        title="Digital Workspace"
        description="Collaborate on documents, brainstorm with whiteboards, and organize your knowledge."
        action={<div className="flex h-12 w-12 items-center justify-center rounded-lg border border-accent/25 bg-accent/10 text-accent"><LayoutDashboard className="h-6 w-6" /></div>}
      />

      <SectionWrapper>
        <div className="mb-6 flex items-center justify-between">
          <h2 className="text-xl font-bold text-white">Your Workspaces</h2>
        </div>

        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {/* Create New Workspace Card */}
          <Card className="rounded-lg border-dashed border-accent/30 bg-accent/5 hover:bg-accent/10 transition">
            <CardContent className="flex h-full flex-col justify-center p-6 text-center">
              <form onSubmit={handleCreate} className="space-y-4">
                <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-accent/20 text-accent">
                  <PlusCircle className="h-6 w-6" />
                </div>
                <h3 className="font-bold text-white">Create Workspace</h3>
                <Input placeholder="Workspace Name" value={newName} onChange={e => setNewName(e.target.value)} required />
                <Input placeholder="Description (Optional)" value={newDesc} onChange={e => setNewDesc(e.target.value)} />
                <Button type="submit" disabled={!newName.trim() || isCreating} className="w-full">
                  {isCreating ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : 'Create'}
                </Button>
              </form>
            </CardContent>
          </Card>

          {/* Workspace List */}
          {workspaces.map(w => (
            <Card key={w.id} className="cursor-pointer transition hover:border-accent/40" onClick={() => navigate(`/workspace/${w.id}`)}>
              <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-lg">
                  <FolderKanban className="h-5 w-5 text-accent" />
                  {w.name}
                </CardTitle>
