              ))}
            </div>
          )}
        </IntelligencePanel>

        <IntelligencePanel title="Rising Stars" icon={TrendingUp}>
          {loading ? <LoadingRows count={5} /> : (
            <div className="space-y-2">
              {data.risingStars.length === 0 ? (
                <p className="py-4 text-center text-sm text-text-muted">No recent high-velocity members detected.</p>
              ) : data.risingStars.map((m, i) => (
                <MemberRow key={m.id} member={m} rank={i + 1} />
              ))}
            </div>
          )}
        </IntelligencePanel>

        <IntelligencePanel title="At Risk (Inactive)" icon={UserMinus}>
          {loading ? <LoadingRows count={5} /> : (
            <div className="space-y-2">
              {data.inactive.length === 0 ? (
                <p className="py-4 text-center text-sm text-text-muted">Member retention is excellent.</p>
              ) : data.inactive.map((m, i) => (
                <div key={m.id} className="flex items-center justify-between rounded-xl border border-status-danger/20 bg-status-danger/5 p-3">
                  <div className="min-w-0">
                    <Link to={`/members/${m.id}`} className="truncate font-bold text-white hover:text-accent">
                      {m.displayName || m.username}
                    </Link>
                    <p className="text-xs text-text-muted">Inactive &gt; 30 days</p>
                  </div>
                  <div className="text-right">
                    <p className="font-heading text-lg font-black text-status-danger">{m.xp || 0}</p>
                    <p className="text-[10px] font-bold uppercase tracking-widest text-text-muted">XP</p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </IntelligencePanel>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Target, Plus } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';
import { UniverseService, UNIVERSE_GOAL_TYPES } from '../../services/firebase/universe';
import { PageContainer, SectionWrapper } from '../../components/layout/LayoutWrappers';
import { PageHeader, LoadingState } from '../../components/ui/UIElements';
import { Card, CardContent } from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';

export default function UniverseGoals() {
  const { user } = useAuth();
  const [goals, setGoals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [title, setTitle] = useState('');
  const [type, setType] = useState('Learning');
  const [saving, setSaving] = useState(false);

  const load = async () => {
    if (!user?.uid) return;
    setLoading(true);
    const list = await UniverseService.getMemberGoals(user.uid);
    setGoals(list);
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, [user?.uid]);

  const createGoal = async (e) => {
    e.preventDefault();
    if (!title.trim() || !user?.uid) return;
    setSaving(true);
    await UniverseService.createMemberGoal(user.uid, { title: title.trim(), type });
    setTitle('');
    await load();
    setSaving(false);
  };

  const bumpProgress = async (goal) => {
    const next = Math.min(100, (goal.progress || 0) + 10);
    await UniverseService.updateMemberGoal(goal.id, {
      progress: next,
      status: next >= 100 ? 'COMPLETED' : 'ACTIVE',
    });
    await load();
  };

  return (
    <PageContainer>
      <PageHeader
        title="Goals"
        description="Learning, research, project, innovation, and career goals — tracked across BeastBuck."
        action={<Target className="h-8 w-8 text-accent" />}
      />

      <SectionWrapper>
        <Card className="rounded-xl">
          <CardContent className="p-4">
            <form onSubmit={createGoal} className="grid gap-3 md:grid-cols-4">
              <Input
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Goal title..."
                className="md:col-span-2"
              />
              <select
                value={type}
                onChange={(e) => setType(e.target.value)}
                className="h-10 rounded-xl border border-border bg-white/5 px-3 text-sm text-white outline-none focus:ring-2 focus:ring-accent"
              >
                {UNIVERSE_GOAL_TYPES.map(t => (
                  <option key={t} value={t}>{t}</option>
                ))}
              </select>
              <Button type="submit" disabled={saving}>
                <Plus className="mr-2 h-4 w-4" /> Add Goal
              </Button>
            </form>
          </CardContent>
        </Card>
      </SectionWrapper>

      <SectionWrapper>
        {loading ? (
          <LoadingState text="Loading goals..." />
        ) : (
          <div className="space-y-3">
            {goals.map(g => (
              <Card key={g.id} className="rounded-xl">
                <CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <p className="text-xs font-bold text-accent">{g.type}</p>
                    <p className="font-bold text-white">{g.title}</p>
                    <p className="text-sm text-text-muted">{g.status} · {g.progress || 0}%</p>
                  </div>
                  <div className="flex items-center gap-3">
                    <div className="h-2 w-32 overflow-hidden rounded-full bg-white/10">
                      <div
                        className="h-full bg-accent transition-all"
                        style={{ width: `${g.progress || 0}%` }}
                      />
                    </div>
                    {g.status === 'ACTIVE' && (
                      <Button size="sm" variant="secondary" onClick={() => bumpProgress(g)}>
                        +10%
                      </Button>
                    )}
                  </div>
                </CardContent>
              </Card>
            ))}
            {goals.length === 0 && (
              <p className="text-center text-text-muted">Create your first goal above.</p>
            )}
          </div>
        )}
      </SectionWrapper>
    </PageContainer>
  );
}
